/****** Object:  StoredProcedure [dbo].[TEST1]    Script Date: 6/23/2023 10:01:53 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[TEST1] 
AS BEGIN
DECLARE @stateId int, @statename nvarchar(255)
DECLARE emp_cursor CURSOR FOR
select StateId,statename from [dbo].[State] group by StateId,statename ORDER BY StateName;
OPEN emp_cursor
FETCH NEXT FROM emp_cursor
INTO @stateId,@statename
WHILE @@FETCH_STATUS = 0
BEGIN
	 if(@statename = 'Wyoming')
		BEGIN
		DECLARE @city_name nvarchar(50);
		--inner cursor
		DECLARE innner_cursor CURSOR FOR   
		
		select CITY from [Tbl_USA_ZipCodes] where STATE = 'WY' group by STATE,CITY;
		
		
		OPEN innner_cursor FETCH NEXT FROM innner_cursor INTO @city_name
		WHILE @@FETCH_STATUS = 0
		BEGIN
		insert into City(CityName,StateId) values(@city_name,@stateId);
		--print CAST(@stateId as varchar(10)) + '--' + @statename + '--' + @city_name
		 FETCH NEXT FROM innner_cursor INTO @city_name 
		END
		CLOSE innner_cursor  
		DEALLOCATE innner_cursor
		
		END
		FETCH NEXT FROM emp_cursor
		INTO @stateId,@statename
END
CLOSE emp_cursor;
DEALLOCATE emp_cursor;

END


exec [dbo].[TEST1] 
GO
/****** Object:  StoredProcedure [dbo].[Udp_GetZipcodesListByCityName]    Script Date: 6/23/2023 10:01:53 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Udp_GetZipcodesListByCityName] @CityName nvarchar(100)  
AS  
SELECT CITY as CityName,[ZIP CODE] as Zipcode FROM [dbo].[Tbl_USA_ZipCodes]  
where CITY =  @CityName  
order by CITY  
  
GO
